CREATE COLUMN TABLE "TEST_AP"."ODDT" ("Numerator" INTEGER CS_INT NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "TrcCode" NVARCHAR(10) NOT NULL , "TrcName" NVARCHAR(30), "DateFrom" LONGDATE CS_LONGDATE, "DateTo" LONGDATE CS_LONGDATE, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LastUpdate" LONGDATE CS_LONGDATE, "WHShaamGrp" NVARCHAR(1) DEFAULT '1' NOT NULL , "DdctPrcnt" DECIMAL(21,6) CS_FIXED, "MaxSum" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("Numerator")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ODDT_CARD" ON "TEST_AP"."ODDT" ( "CardCode" ASC, "WHShaamGrp" ASC, "TrcCode" ASC )